const formatter = new Intl.NumberFormat("en-KE", { style: "currency", currency: "KES", maximumFractionDigits: 0 });
const today = new Date().toISOString().slice(0, 10);

function formatKes(value: number | string | null | undefined) {
  return formatter.format(Number(value ?? 0));
}

function formatDate(value: Date | string | null | undefined) {
  if (!value) return "—";
  return format(new Date(value), "d MMM yyyy");
}

function downloadCsv(filename: string, rows: Array<Record<string, string | number | null | undefined>>) {
  if (rows.length === 0) return toast.info("There are no records to export yet.");
  const headers = Array.from(new Set(rows.flatMap(row => Object.keys(row))));
  const escape = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`;
  const csv = [headers.join(","), ...rows.map(row => headers.map(header => escape(row[header])).join(","))].join("\n");
  const objectUrl = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  const link = document.createElement("a");
  link.href = objectUrl;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(objectUrl);
  toast.success("Export downloaded. It can be opened in Excel.");
}

export function roleNavigation(role?: string, isPlatformAdmin = false): NavigationItem[] {
  const shared = [{ id: "dashboard", label: "Overview", icon: LayoutDashboard }];
  if (["super_admin", "principal", "deputy_principal", "bursar"].includes(role ?? "")) {
    return [...shared, ...(role === "super_admin" && isPlatformAdmin ? [{ id: "platform", label: "Platform monitor", icon: Building2 }] : []), { id: "students", label: "Students", icon: Users }, { id: "teachers", label: "Teachers", icon: UserRoundCog }, { id: "academics", label: "Academics", icon: BookOpenCheck }, { id: "homework", label: "Assignments", icon: FileText }, { id: "attendance", label: "Attendance", icon: ClipboardCheck }, { id: "fees", label: "Fees", icon: WalletCards }, { id: "timetable", label: "Timetable", icon: CalendarDays }, { id: "calendar", label: "Calendar & notices", icon: Megaphone }, { id: "messages", label: "Messages", icon: Bell }, { id: "operations", label: "Daily tasks", icon: ListChecks }, { id: "advanced", label: "Search & alerts", icon: Settings2 }, { id: "documents", label: "IDs & bulk", icon: FileBarChart }, ...(role !== "bursar" ? [{ id: "manage", label: "Record maintenance", icon: Settings2 }] : []), { id: "reports", label: "Reports", icon: FileBarChart }, { id: "audit", label: "Audit log", icon: ShieldCheck }, ...(role === "super_admin" ? [{ id: "settings", label: "Settings", icon: Settings2 }] : [])];
  }
  if (["teacher", "class_teacher"].includes(role ?? "")) {
    return [...shared, { id: "students", label: "My classes", icon: Users }, { id: "academics", label: "Marks & results", icon: BookOpenCheck }, { id: "homework", label: "Assignments", icon: FileText }, { id: "attendance", label: "Attendance", icon: ClipboardCheck }, { id: "timetable", label: "Timetable", icon: CalendarDays }, { id: "calendar", label: "Calendar & notices", icon: Megaphone }, { id: "messages", label: "Messages", icon: Bell }];
  }
  if (role === "parent") return [...shared, { id: "students", label: "My children", icon: Users }, { id: "academics", label: "Results", icon: BookOpenCheck }, { id: "homework", label: "Assignments", icon: FileText }, { id: "attendance", label: "Attendance", icon: ClipboardCheck }, { id: "fees", label: "Fees", icon: WalletCards }, { id: "timetable", label: "Timetable", icon: CalendarDays }, { id: "calendar", label: "Calendar & notices", icon: Megaphone }, { id: "messages", label: "Messages", icon: Bell }];
  return [...shared, { id: "students", label: "My profile", icon: Users }, { id: "academics", label: "Results", icon: BookOpenCheck }, { id: "homework", label: "Assignments", icon: FileText }, { id: "attendance", label: "Attendance", icon: ClipboardCheck }, { id: "fees", label: "Fee status", icon: WalletCards }, { id: "timetable", label: "Timetable", icon: CalendarDays }, { id: "calendar", label: "Calendar & notices", icon: Megaphone }];
}

